import java.io.*;

public class Main {
    private static final int BUFSIZE = 1 << 16;
    private static final byte[] buffer = new byte[BUFSIZE];
    private static int bufPos = 0, bufLen = 0;
    private static final InputStream in = System.in;

    private static int readByte() throws IOException {
        if (bufPos == bufLen) {
            bufLen = in.read(buffer, 0, BUFSIZE);
            bufPos = 0;
            if (bufLen == -1) return -1;
        }
        return buffer[bufPos++];
    }

    private static long nextLong() throws IOException {
        int b = readByte();
        while (b != -1 && (b < '0' || b > '9')) b = readByte();
        long ret = 0;
        while (b >= '0' && b <= '9') {
            ret = ret * 10 + (b - '0');
            b = readByte();
        }
        return ret;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) a[i] = (int) nextLong();

        int l = 0, r = n - 1;
        long ls = a[0], rs = a[n - 1];
        long count = 0;

        while (l < r) {
            if (ls == rs) {
                l++;
                r--;
                ls = a[l];
                rs = a[r];
            } else if (ls < rs) {
                l++;
                ls += a[l];
                count++;
            } else {
                r--;
                rs += a[r];
                count++;
            }
        }

        System.out.print(count);
    }
}
